function omoDocumentsUiT(string $key, array $variables = []): string
{
    static $bundles = [];
    $sourceLang = omoDocumentsUiSourceLang();
    $locale = omoGetTranslationLocale();
    $bundle = $bundles[$locale] ??= loadTranslationBundle('omo_documents_ui', $locale, $sourceLang);
    return t($key, $variables, $bundle, $sourceLang);
}
